pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testRegression_property() public {
        // Set owner to a different address
        address newOwner = address(0x1234);

        // Call changeOwner as the owner (which is address(this) by default)
        vm.prank(c._owner());
        c.changeOwner(newOwner);

        // Now call allowance to trigger the difference (the mutation removed the assignment in changeOwner)
        c.allowance(address(0), address(0));

        // In reference: _owner is newOwner; in bug: _owner is still the original deployer (address(this))
        assertTrue(c._owner() == newOwner);
    }
}

