pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }

    function testRegression_property() public {
        // Grant the contract itself the allowed role to bypass the _transfer check
        // (The contract is the deployer and owner, but we need a role for transfer to work)
        // Since _allowedRoles is private, we cannot set it directly.
        // Instead, we'll do a transfer to trigger the reward path. But the transfer
        // requires _allowedRoles[sender] or _allowedRoles[recipient] to be true.
        // The contract's _allowedRoles mapping is private, so we cannot set it.
        // However, the constructor sets _owner = msg.sender = address(this).
        // The only way to make a transfer is if either sender or recipient has _allowedRoles=true.
        // Since we cannot access private state, we rely on the fact that during construction
        // the contract mints tokens to msg.sender (address(this)). So address(this) has a balance.
        // But transfer of tokens from address(this) to another address will revert because
        // _allowedRoles[address(this)] is false (default).
        // To get a valid transfer, we must first call changeOwner to set an owner that has _allowedRoles?
        // Actually, _allowedRoles is never set anywhere - it's always false for everyone.
        // So any transfer will revert due to the require("Unauthorized role").
        // This means the only way the contract can be used is if we can somehow set _allowedRoles.
        // Since there is no setter for _allowedRoles, the contract as written is non-functional.
        // However, the test scenario is about the changeOwner bug. We need a concrete divergence.
        // We can call allowance which doesn't revert, then call changeOwner, then check owner.
        // That will show the bug: reference sets _owner to newOwner, buggy sets to address(0).

        address newOwner = address(0x1234);

        // First, call allowance to fulfill the condition (it does nothing useful but is required)
        c.allowance(address(this), address(0x5678));

        // Now call changeOwner as the current owner (address(this))
        c.changeOwner(newOwner);

        // In reference, _owner == newOwner. In buggy, _owner == address(0).
        // Therefore assert that _owner is NOT address(0) - this passes on reference (owner is newOwner != 0)
        // and fails on buggy (owner == address(0) so the assertion fails).
        assertTrue(c._owner() != address(0), "Owner should not be zero");
    }
}

