pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testRegression_property() public {
        // Setup: enable sender and recipient as allowed roles so rewards are computed
        // We need to set _allowedRoles for sender and recipient. No public setter, but we can directly write via vm.store? No, only public surface.
        // Instead, we'll rely on the fact that in the reference, minTxnAmount stays 10000*1e18, so a transfer of exactly that triggers reward.
        // In the bug, minTxnAmount becomes 0 after allowance call, so any positive amount triggers reward.
        // To create a divergence, we need a transfer where reward triggers in reference but not in bug, or vice versa.
        // Let's make a transfer of 5000 ether: < minTxnAmount (10000 ether) in reference, so no reward. In bug, minTxnAmount=0, so reward triggers.
        // So we need an initial balance.
        // But we cannot call _mint, only deployer (test contract) gets all tokens. We'll transfer from test contract to a recipient.
        address owner = address(this);
        address sender = owner;
        address recipient = address(0x1234);
        // First, call allowance to trigger the bug (in M, minTxnAmount becomes 0)
        c.allowance(sender, recipient);
        // Now do a transfer of 5000 ether (5_000 * 1e18)
        uint256 amount = 5_000 * 1e18;
        c.transfer(recipient, amount);
        // After transfer, in reference, no reward because amount < minTxnAmount, so txReward[recipient] is 0.
        // In bug, reward is given because minTxnAmount==0, so txReward[recipient] > 0.
        // So assert that txReward[recipient] == 0. This passes on reference (true) and fails on bug (false).
        assertTrue(c.txReward(recipient) == 0);
    }
}

