pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testRegression_property() public {
        // Give the contract a large balance to distribute rewards
        vm.deal(address(this), 1 ether);
        // The reference decimals is 18, but we rely on the bug's hardcoded 18 having the same effect externally
        // However, the bug changes the internal rate calculation through tokenFromReflection
        // Trigger a transfer that gives the contract enough balance
        c.transfer(address(this), 10000 * 1e18);
        // Now transfer to trigger reward (tAmount >= minTxnAmount)
        uint256 amount = 10000 * 1e18;
        c.transfer(address(0x1), amount);
        // The buggy version's hardcoded decimals() affects balanceOf calculations differently
        uint256 balanceRef = c.balanceOf(address(0x1));
        // In the reference, the reward is distributed; in the bug, the reward amount differs
        uint256 expectedReward = amount * 5 / 10000;
        // The buggy version's hardcoded 18 in decimals() changes _getRate() and tokenFromReflection
        // causing the observed balance to be different from the expected one
        // Assert that the balance is NOT equal to the expected reference reward
        assertTrue(balanceRef != amount + expectedReward, "Balance should differ from buggy");
    }
}

